pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is too small to fit any likely future item 
    // (items are 10..80, so < 10 is often "dead"), penalize heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 2. Open Bin Pressure: If we have many open bins, we want to consolidate.
    // Penalize opening a new bin (bin_residual == bin_capacity) if we have fitting bins available.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 200.0 * (open_bins_count as f64);
    }

    // 3. Lookahead Sensitivity: If the next item is large, avoid leaving a post_residual
    // that is just slightly smaller than the next_item_size.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 4. Mean Residual Balancing: Prefer bins that stay close to the current average 
    // to keep the bin distribution uniform.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    // 5. Progression Weighting: As we reach the end of the stream, prioritize 
    // clearing out the most filled bins (Best Fit behavior).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space remaining (Best Fit principle)
    // We penalize small residuals that are too small to fit common items (10-30 range)
    let mut score = post;

    // Penalty for leaving a 'dead zone' (residual space that is likely too small for future items)
    // As the stream progresses, we become more conservative about creating small fragments.
    if post < 25.0 && post > 0.0 {
        score += (25.0 - post) * (1.0 + progress * 2.0);
    }

    // Lookahead coupling: If a next item exists, penalize bins that cannot fit it
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Dynamic preference for filling bins early vs late
    // If we have many open bins, we favor closing the gap in existing ones.
    // If fitting_bins_count is 1, it's a critical bin; reduce score to prioritize it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of current bins is high (we have plenty of space)
        // or if we are at the very start.
        score += mean_residual * 0.5;
        score += (1.0 - progress) * 15.0;
    }

    score
}

