    // 2. Harmonic sensitivity: prioritize residuals that match potential next_item_size
    // If the post_residual is close to the next_item_size, we reward it heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact or near-exact matches for the next item to minimize fragmentation
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 2.5;
        } else {
            // Penalize bins that cannot fit the next item if we are running out of space
            score += 50.0;
        }
    }

    // 3. Prevent opening new bins prematurely
    // If we have open bins, penalize the "new bin" candidate (bin_residual == bin_capacity)
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 150.0;
    }

    // 4. Harmonic thresholding:
    // If a bin has a residual that is a multiple of common item sizes, keep it open for future items.
    // If post_residual is very small (e.g., < 5), it's "dead space", so penalize it.
    if post_residual < 5 && post_residual > 0 {
        score += 40.0;
    }

    // 5. Progression scaling:
    // As we near the end of the stream, prioritize packing tighter (minimize open_bins_count)
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 10.0);

    // 6. Bias toward filling bins that are already partially full (high mean_residual vs current)
    // If this bin is below the mean_residual, it is a "good" bin to fill to keep others open.
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    }

    score
}

