        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can fit the item
            score += 60.0;
        }
        // Late-game bias: be more aggressive with new bins as we approach the end
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 10.0;
    }

    // 5. Mean residual balancing: if this bin is significantly emptier than the average,
    // favor filling it to consolidate space.
