        if post_residual >= next_item_size {
            score -= 15.0; // Strong reward for keeping the bin viable for the next item
        } else {
            score += 5.0; // Mild penalty if the next item is forced into a new bin
        }
    }

    // 3. Density Balancing: If we have many open bins, prioritize filling the tightest
    // ones to consolidate space. If we have few, be more conservative.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (1.0 - fill_ratio) * 10.0;

    // 4. New Bin Thresholding: If this is a new bin (bin_residual == bin_capacity),
    // only pick it if the alternative is creating a very poor fit (sliver) elsewhere.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, but scale it down if open bins are already full
        score += 45.0 - (open_bins_count as f64 * 0.5);
    } else {
        // Reward bins that have a residual close to the mean, promoting balanced usage
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;
    }

    // 5. Last Chance Logic: If this is the only bin that fits the item, make it very attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
